Change(genesis='e30427e699992327267add669c3bc989f6d16525ba6f493121eec7778638e0ce', deps=('8aa4b91de8cb083e9b304fe6d4711aba31d5447f39954538f47f1a9cb3f7f9b0',), event=Authored(todo='megaroadmap', at=datetime(2026, 11, 20, 23, 4, 17, 890274), actor='bmabsout', kind='todo', created=datetime(2026, 11, 20, 0, 0, 0), body="The roadmap is the plan: the work of every project store reads as one list, most urgent first, with the store and the package each task lives in; a plan's stages are tasks that wait on each other, also across stores, so urgency reaches what blocks it; each task says what is in work and what it waits on; and every landed change marks the task it advances, not only the one it completes.", spec=Flat(value=0.4), rationale=("The roadmap is the plan's one source of truth, and today it drifts from", 'the code and is read one store at a time.'), category='', waiting_on='', detail='In work since 2026-11-20: the first change is a store a deployment follows and never writes, and one list over every store; the page, the mark a landed change leaves on the task it advances, and waits across stores follow.\n\nState on 2026-11-20: the first part landed in release 2.1.191. The command that lists open tasks reads every store of the deployment and every followed store as one list, each row with its store and its package, ordered by its reading under the waits; a followed store is a read-only copy of a git branch, brought up to date by a fetch. Left: a reference to a task of a store by its genesis, so a wait into a public store counts; the page of the one list; the train recording what a landing advances; a timer for the fetch.', source=None, subtodos=(), notes=(), note=''))